macro define(name: code, rows: span[code-token]) {
  let entries = parse-rows(rows).as-span()
  validate(entries)

  let cb-storage = code-builder/new()
  let cb = cb-storage.&

  cb.write-code("type $name = either { ")
  for en in entries {
    if it-index > 0 cb.write(", ")
    cb.write-token(en.name)
    if payload-type(en) is :some ty {
      cb.write("(")
      cb.write-code(ty)
      cb.write(")")
    }
  }
  cb.write(" }\n")

  cb.block("ns for $name", fn[cb, name, entries]. emit-parse-fn(cb, name, entries))
  emit-print-impl(cb, name, entries)

  cb.build()
}

ability shape {
  fn area(self: *self): f64
  fn name(self: *self): string
  fn sides(): int
  fn describe(self: *self): string {
    "${self.name()} area=${self.area()} sides=${shape@(self)/sides()}"
  }
}

impl shape for circle {
  fn area(self: *circle): f64 { 3.14159 * self.radius * self.radius }
  fn name(_self: *circle): string { "circle" }
  fn sides(): int { 0 }
}

impl shape for rect {
  fn area(self: *rect): f64 { self.w * self.h }
  fn name(_self: *rect): string { "rect" }
  fn sides(): int { 4 }
  fn describe(self: *rect): string { "${self.w}x${self.h} rect" }
}

fn bigger[t: shape](a: *t, b: *t): *t {
  if a.area() > b.area() a else b
}

ability loud {
  fn shout(self: *self): string
}

impl[t: shape] loud for t {
  fn shout(self: *t): string { "${self.name()}!" }
}

type vec2 = { x: f64, y: f64 }

impl add for vec2 {
  fn add(self: vec2, rhs: vec2): vec2 { .{ x = self.x + rhs.x, y = self.y + rhs.y } }
}

type auth = either {
  anonymous,
  bearer(string),
  basic({ user: string, pass: string }),
}
type request = {
  method: string,
  path: string,
  auth: auth,
  body: ?string,
}

fn known(user: string, pass: string): bool {
  user == "ada" and pass.len() >= 8
}

fn handle(r: request): string {
  require r is .{
      method = "POST",
      path,
      auth = :basic .{ user, pass },
      body = :some body,
    }
    and path.starts-with("/api/")
    and known(user, pass)
    else { return "401 for ${r.method} ${r.path}" }
  "${user} posted ${body.len()} bytes to $path"
}

